// ==========================================
// AUTHENTICATION
// ==========================================
app.post('/api/signup', async (req, res) => {
  try {
    const username = typeof req.body.username === 'string' ? req.body.username.trim() : '';
    const password = typeof req.body.password === 'string' ? req.body.password : '';

    if (!username || !password) return res.status(400).json({ error: 'Username and passkey are required.' });

    const existingPlayer = await User.findOne({ username });
    if (existingPlayer) return res.status(409).json({ error: 'Recruit ID already exists. Initiate login instead.' });

    const player = await User.create({ username, password: await hashPassword(password) });
    return res.status(201).json({ message: 'New terminal connection established.', player: serializePlayer(player) });
  } catch (error) {
    return res.status(500).json({ error: 'Server singularity error. Try again.' });
  }
});

app.post('/api/login', async (req, res) => {
  try {
    const username = typeof req.body.username === 'string' ? req.body.username.trim() : '';
    const password = typeof req.body.password === 'string' ? req.body.password : '';

    const player = await User.findOne({ username });
    if (!player) return res.status(404).json({ error: 'Agent not found. Verify recruit ID.' });
    if (!(await verifyPassword(password, player.password))) return res.status(401).json({ error: 'Invalid passkey. Access denied.' });

    if (!player.password.startsWith('scrypt$')) {
      player.password = await hashPassword(password);
      await player.save();
    }

    return res.json({ message: 'Welcome back, Explorer.', player: serializePlayer(player) });
  } catch (error) {
    return res.status(500).json({ error: 'Server singularity error. Try again.' });
  }
});

